import pandas as pd

def clean(df):
    df = df.copy()
    df['body_mass_g'] = df['body_mass_g'].astype(str).str.replace(',', '', regex=False).astype(float)
    df['sex'] = df['sex'].astype(str).str.strip()
    return df

def answer(df):
    df = clean(df)
    return df.groupby('sex')['body_mass_g'].mean().to_dict()
